From b1f986157345cc9c7659d760c60a5631367f2a74 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 03:24:50 +0100
Subject: [PATCH] emergencywindow: suggest recovery steps that work

The broken locker message suggested VT 1 or 2, usually taken by the
display manager or the session, and printed F0 or no session ID when
they are unknown. Now it suggests VT 3 or 4, SSH, or list-sessions.

BUG: 473247
---
 emergencywindow.cpp | 39 ++++++++++++++++++++++++++-------------
 1 file changed, 26 insertions(+), 13 deletions(-)

diff --git a/emergencywindow.cpp b/emergencywindow.cpp
index 8dae42e3..d486e9f6 100644
--- a/emergencywindow.cpp
+++ b/emergencywindow.cpp
@@ -56,31 +56,44 @@ void EmergencyWindow::paintEvent(QPaintEvent *)
         "of which could be found on your system.");
     auto text_ck = ki18nc("%1 = other terminal",
                           "The screen locker is broken and unlocking is not possible anymore.\n"
-                          "In order to unlock it, switch to a virtual terminal (e.g. Ctrl+Alt+F%1),\n"
-                          "log in as root and execute the command:\n\n"
+                          "In order to unlock it, switch to a virtual terminal (e.g. Ctrl+Alt+F%1,\n"
+                          "or another F key if that one shows nothing), log in as root and\n"
+                          "execute the command:\n\n"
                           "# ck-unlock-session <session-name>\n\n");
-    auto text_ld = ki18nc("%1 = other terminal, %2 = session ID, %3 = this terminal",
+    auto text_ld = ki18nc("%1 = other terminal, %2 = unlock command, %3 = this terminal",
                           "The screen locker is broken and unlocking is not possible anymore.\n"
-                          "In order to unlock it, switch to a virtual terminal (e.g. Ctrl+Alt+F%1),\n"
-                          "log in to your account and execute the command:\n\n"
-                          "loginctl unlock-session %2\n\n"
+                          "In order to unlock it, switch to a virtual terminal (e.g. Ctrl+Alt+F%1,\n"
+                          "or another F key if that one shows nothing), log in to your account\n"
+                          "and execute the command:\n\n"
+                          "%2\n\n"
                           "Then log out of the virtual session by pressing Ctrl+D, and switch\n"
                           "back to the running session (Ctrl+Alt+F%3).\n"
                           "Should you have forgotten the instructions, you can get back to this\n"
                           "screen by pressing Ctrl+Alt+F%3\n\n");
+    auto text_ld_novt = ki18nc("%1 = unlock command",
+                               "The screen locker is broken and unlocking is not possible anymore.\n"
+                               "In order to unlock it, log in to your account from another computer\n"
+                               "(e.g. over SSH) and execute the command:\n\n"
+                               "%1\n\n");

     auto haveService = [](QString service) {
         return QDBusConnection::systemBus().interface()->isServiceRegistered(service);
     };
+    const int virtualTerminalId = qEnvironmentVariableIntValue("XDG_VTNR");
+    const int otherTerminalId = virtualTerminalId == 3 ? 4 : 3;
     if (haveService(QStringLiteral("org.freedesktop.ConsoleKit"))) {
-        auto virtualTerminalId = qgetenv("XDG_VTNR").toInt();
-        text = text_ck.subs(virtualTerminalId == 2 ? 1 : 2);
+        text = text_ck.subs(otherTerminalId);
     } else if (haveService(QStringLiteral("org.freedesktop.login1"))) {
-        text = text_ld;
-        auto virtualTerminalId = qgetenv("XDG_VTNR").toInt();
-        text = text.subs(virtualTerminalId == 2 ? 1 : 2);
-        text = text.subs(QString::fromLocal8Bit(qgetenv("XDG_SESSION_ID")));
-        text = text.subs(virtualTerminalId);
+        const QString sessionId = qEnvironmentVariable("XDG_SESSION_ID");
+        const QString command = sessionId.isEmpty() ? i18nc("unlock command when the session ID is unknown",
+                                                            "loginctl unlock-session <ID>\n\n"
+                                                            "where <ID> is this session's ID as listed by \"loginctl list-sessions\"")
+                                                    : QStringLiteral("loginctl unlock-session ") + sessionId;
+        if (virtualTerminalId > 0) {
+            text = text_ld.subs(otherTerminalId).subs(command).subs(virtualTerminalId);
+        } else {
+            text = text_ld_novt.subs(command);
+        }
     }

     p.setPen(Qt::white);
-- 
